select distinct parent_id from sys_menu where menu_id in
#{menuId}
and parent_id is not null and parent_id != 0

mapper.update:
update sys_tenant
tenant_name = #{tenantName}, contact_user = #{contactUser}, contact_phone = #{contactPhone}, account_count = #{accountCount}, expire_time = #{expireTime}, status = #{status}, remark = #{remark}, edition = #{edition}, ai_enabled = #{aiEnabled}, voice_enabled = #{voiceEnabled}, ocr_enabled = #{ocrEnabled}, scan_enabled = #{scanEnabled}, monthly_quota_text = #{monthlyQuotaText}, monthly_quota_voice = #{monthlyQuotaVoice}, annual_quota_text = #{annualQuotaText}, annual_quota_voice = #{annualQuotaVoice}, cancel_requested = #{cancelRequested}, cancel_requested_at = #{cancelRequestedAt}, cancel_reason = #{cancelReason}, update_by = #{updateBy}, update_time = sysdate()
where tenant_id = #{tenantId}

UPDATE sys_tenant
SET ai_points = ai_points - #{cost},
    ai_points_total_used = ai_points_total_used + #{cost}
WHERE tenant_id = #{tenantId}
  AND ai_enabled = 1
  AND ai_points >= #{cost}

UPDATE sys_tenant
SET ai_points = ai_points + #{amount},
    ai_points_total_charged = ai_points_total_charged + #{amount}
WHERE tenant_id = #{tenantId}
  AND del_flag = '0'
